WITH with_windows AS (SELECT *, LAG(revenue, 1) OVER (PARTITION BY product_id ORDER BY sale_date, id) prev_revenue, LAST_VALUE(units, TRUE) OVER (PARTITION BY store_id, product_id ORDER BY revenue, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_units, DENSE_RANK() OVER (PARTITION BY product_id, store_id ORDER BY units DESC NULLS FIRST) units_dense_rank FROM store_sales) SELECT s.id, s.store_id, s.product_id, s.sale_date, s.units, s.revenue, s.prev_revenue, s.last_known_units, (SELECT MAX(t2.quantity) FROM inventory t2 WHERE t2.product_id = s.product_id) AS max_inventory_quantity FROM with_windows s ORDER BY id;
